// Release 735 (the full-game review's dungeon and interior findings): new interiors, deep-v2 dungeons and canyon craters are
// generated by new, pinned versions; anything an existing journey generated before regenerates exactly as it was.
import test from 'node:test';
import assert from 'node:assert/strict';
import { freshSave } from '../src/types.ts';
import { Game, generatePinnedDungeon } from '../src/game.ts';
import { LETHAL_KINDS } from '../src/landscape.ts';
import { BUILDINGS, buildingPlan, generateBuildingFloor } from '../src/great-buildings.ts';
import { generateCompoundFloor, compoundTopology } from '../src/compounds.ts';
import { castlePartPlan, generateCastleFloor } from '../src/castles.ts';
import { labyrinthPlan, generateLabyrinthChamber } from '../src/labyrinths.ts';
import { DEEP_PLACEMENT, generateDeepV2Dungeon } from '../src/deep-dungeons.ts';
import { CANYON, generateCanyon } from '../src/canyon.ts';
import { PENTAGON, pentagonPlan } from '../src/pentagon.ts';
import { LANDSCAPE_VERSION } from '../src/landscape.ts';
import { hauntPlan, hauntSpawns, HAUNT } from '../src/haunts.ts';

const save = (seed) => { const s = freshSave(); s.seed = seed; return s; };
const js = (m) => JSON.stringify(m);
const standable = (t) => !!t && !t.blocked && !LETHAL_KINDS.has(t.kind) && !t.hole;
// 4-way flood from `from`; `pass(t)` for tiles stood on; `jump` lets a gallery's one-tile gap be jumped
const flood = (map, from, { pass = standable, jump = false } = {}) => { const W = map.width, H = map.height || map.tiles.length / W, seen = new Set([from.y * W + from.x]), q = [from];
  while (q.length) { const p = q.pop(); for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { let x = p.x + dx, y = p.y + dy; if (x < 0 || y < 0 || x >= W || y >= H) continue; let t = map.tiles[y * W + x];
    if (!pass(t)) { if (!jump || !t || t.blocked) continue; x += dx; y += dy; t = map.tiles[y * W + x]; if (!pass(t)) continue; } const k = y * W + x; if (!seen.has(k)) { seen.add(k); q.push({ x, y }); } } }
  return seen; };
const near = (map, seen, o, r = 1.5) => { const W = map.width; for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) { const x = Math.round(o.x) + dx, y = Math.round(o.y) + dy; if (seen.has(y * W + x) && Math.hypot(x - o.x, y - o.y) < r) return true; } return false; };

test('interior versions are pinned per interior: fresh interiors take the current version, anything generated before keeps version 1', () => {
  assert.equal(BUILDINGS.interior.version, 4);
  const s = save('TIM1'), id = 'building:TIM1:-24:-16:hive:4r';
  generatePinnedDungeon(s, `${id}:f1`); assert.equal(s.consequences.dungeons[`${id}:f1`].interiorVersion, BUILDINGS.interior.version);
  generatePinnedDungeon(s, `${id}:f3`); assert.equal(s.consequences.dungeons[`${id}:f3`].interiorVersion, BUILDINGS.interior.version, 'later floors follow the first');
  // an existing journey: a floor of it generated by an earlier release (a history with its generator and no interior version)
  const old = save('TIM1'); old.consequences.dungeons[`${id}:f1`] = { discovered: true, visits: 1, generatorVersion: 5, layoutVersion: 1 };
  const m = generatePinnedDungeon(old, `${id}:f4`); assert.equal(old.consequences.dungeons[`${id}:f4`].interiorVersion, 1);
  assert.equal(js(m.tiles), js(generateBuildingFloor('TIM1', `${id}:f4`).tiles), 'laid out exactly as before');
  assert.equal(js(m.enemySpawns), js(generateBuildingFloor('TIM1', `${id}:f4`).enemySpawns));
  // a castle wing entered first by a side door on an upper floor is still one interior
  const c = save('ZQ3'), k = 'castle:ZQ3:-81:-57:k:3'; generatePinnedDungeon(c, `${k}:f2`); generatePinnedDungeon(c, `${k}:f1`);
  assert.equal(c.consequences.dungeons[`${k}:f1`].interiorVersion, BUILDINGS.interior.version);
  // a session area of a sibling floor (an exact-resume snapshot) pins version 1 too
  const r = save('TIM1'); r.session.areas[`${id}:f2`] = { enemies: [] }; generatePinnedDungeon(r, `${id}:f1`); assert.equal(r.consequences.dungeons[`${id}:f1`].interiorVersion, 1);
});

test('D1/D11: a gallery of gaps keeps the platform beside a bottom or right door, so every key is placed and every vault can be reached', () => {
  const lost = ['labyrinth:ZQ3:-85:-77:hive', 'labyrinth:A7:61:69:keep', 'labyrinth:A7:10:18:keep', 'labyrinth:A7:-69:-61:apartment', 'labyrinth:ZQ3:-93:-85:apartment', 'labyrinth:KX9:-45:-37:apartment'];
  for (const base of lost) { const P = labyrinthPlan(base), seed = base.split(':')[1];
    const keys = (V) => new Set(P.nodes.flatMap((q) => generateLabyrinthChamber(seed, `${base}:f${q.n + 1}`, V).objects.filter((o) => o.kind === 'labKey').map((o) => o.keyId)));
    assert.ok(P.gates.some((g) => !keys(1).has(g.key.id)), `${base}: version 1 stays as it was (a key lost)`);
    const k2 = keys(2); for (const g of P.gates) assert.ok(k2.has(g.key.id), `${base}: ${g.key.id} placed in version 2`);
    // solve version 2: passages, keys before their doors, barred shortcuts, falls
    const maps = P.nodes.map((q) => generateLabyrinthChamber(seed, `${base}:f${q.n + 1}`, 2)), got = new Set(), opened = new Set(), seen = new Set([0]); let changed = true;
    while (changed) { changed = false; for (const n of [...seen]) { const m = maps[n], reach = flood(m, m.entry, { jump: m.building.kind === 'gaps' });
      for (const o of m.objects) { if (!near(m, reach, o)) continue; if (o.kind === 'labKey' && !got.has(o.keyId)) { got.add(o.keyId); changed = true; }
        if (!o.toId || (o.lock && !got.has(o.lock)) || (o.barred && !opened.has(o.shortcutKey))) continue; if (o.shortcutOpens && !opened.has(o.shortcutOpens)) { opened.add(o.shortcutOpens); changed = true; }
        const j = Number(o.toId.split(':f').pop()) - 1; if (!seen.has(j)) { seen.add(j); changed = true; } } } }
    assert.ok(seen.has(P.end), `${base}: the vault can be reached`); }
  // galleries: the way in always reaches more than its own tile
  for (const base of ['labyrinth:ZQ3:-85:-77:hive', 'labyrinth:A7:58:66:keep', 'labyrinth:ZQ3:74:82:hive']) { const P = labyrinthPlan(base), seed = base.split(':')[1];
    for (const q of P.nodes.filter((n) => n.kind === 'gaps')) { const m = generateLabyrinthChamber(seed, `${base}:f${q.n + 1}`, 2); assert.ok(flood(m, m.entry, { jump: true }).size > 8, `${base} f${q.n + 1}: not an island`); } }
});

test('D2: behind the sealed final gate, no deep water cuts the corridor to the final boss (deep-v2 placement 2)', () => {
  const id = 'dungeon:KX9:g1:-17:-5:deep-v2:loop', gate = (t) => standable(t) || (!!t && (t.kind === 'sealedGate' || !!t.gateId));
  const boss = (m) => m.enemySpawns.find((e) => e.dungeonRole === 'finalBoss');
  const v1 = generateDeepV2Dungeon('KX9', id), v2 = generateDeepV2Dungeon('KX9', id, { deepPlacement: 2 });
  assert.ok(!near(v1, flood(v1, v1.entry, { pass: gate }), boss(v1), 2.2), 'version 1 stays as it was (cut off)');
  const seen = flood(v2, v2.entry, { pass: gate }); assert.ok(near(v2, seen, boss(v2), 2.2), 'the final boss can be reached once the gate opens');
  for (const o of v2.objects.filter((o) => o.kind === 'deepPortal')) assert.ok(near(v2, seen, o), `${o.id} reachable`);
  assert.equal(v2.deepPlacement, DEEP_PLACEMENT.version);
  const s = save('KX9'); generatePinnedDungeon(s, id); assert.equal(s.consequences.dungeons[id].deepPlacement, DEEP_PLACEMENT.version, 'a fresh history pins placement 2');
});

test('D4/D5: the Resonant Dead\'s tones and the Oath Doors stand where they can be used (threefold layout 2, placement 2)', () => {
  for (const [seed, id] of [['TIM1', 'dungeon:TIM1:g1:11:-2:deep-v2:threefold'], ['ZQ3', 'dungeon:ZQ3:g1:-30:-26:deep-v2:threefold'], ['TIM1', 'dungeon:TIM1:g1:-30:-26:deep-v2:threefold']]) {
    const v1 = generateDeepV2Dungeon(seed, id, { threefoldLayout: 2 }), m = generateDeepV2Dungeon(seed, id, { threefoldLayout: 2, deepPlacement: 2 });
    const hub = flood(m, m.hub), entry = flood(m, m.entry);
    for (const o of m.objects.filter((o) => o.storyId)) assert.ok(near(m, hub, o), `${id}: ${o.id} by reachable floor`);
    const short = m.objects.filter((o) => o.kind === 'deepShortcut'); assert.ok(short.length);
    for (const o of short) { assert.ok(near(m, entry, o), `${id}: ${o.id} usable`); assert.ok(o.cells.some((c) => c.x === o.x && c.y === o.y), 'on one of its own cells'); }
    assert.equal(js(m.tiles.map((t) => [t.kind, t.blocked])), js(generateDeepV2Dungeon(seed, id, { threefoldLayout: 2, deepPlacement: 2 }).tiles.map((t) => [t.kind, t.blocked])), 'deterministic');
    assert.ok(v1.objects.some((o) => (o.storyId && !near(v1, flood(v1, v1.hub), o)) || (o.kind === 'deepShortcut' && !near(v1, flood(v1, v1.entry), o))), `${id}: version 1 stays as it was`); }
});

test('D3: the Regent\'s Hoard stays shut while the Regent lives, then opens and pays the grade her fall decided', () => {
  const g0 = new Game(save('TIM1'), 0); let c = null; for (let cx = -64; cx <= 64 && !c; cx += PENTAGON.every) for (let cy = -64; cy <= 64 && !c; cy += PENTAGON.every) if (g0.pentagonHere(cx, cy)) c = { cx, cy };
  assert.ok(c); const s = save('TIM1'); s.atlas = { [`${c.cx + 1},${c.cy + 1}`]: { landscapeVersion: LANDSCAPE_VERSION, pentVersion: 5 } };
  const g = new Game(s, 0), P = pentagonPlan('TIM1', c.cx, c.cy, 5), q = P.nodes.find((n) => n.id === `h${P.nh - 1}`);
  g.save.session.activeDungeonId = `${P.base}:f${q.n + 1}`; g.loadArea('dungeon', false);
  const hoard = g.map.objects.find((o) => o.kind === 'chest' && o.id === 'building-cache'), regent = g.enemies.find((e) => e.id.endsWith(':guardian'));
  assert.ok(hoard && regent); g.player.x = hoard.x; g.player.y = hoard.y; const owned = (g.save.tesseracts?.owned || []).length;
  const r = g.interact('open', hoard.id); assert.equal(r.ok, false); assert.equal(r.message, PENTAGON.messages.hoardHeld); assert.equal(hoard.state, 'closed');
  assert.equal((g.save.tesseracts?.owned || []).length, owned, 'no Tesseract forfeited');
  regent.hp = 0; regent.dead = true; g.defeatEnemy(regent); const H = g.save.consequences.dungeons[`${P.base}:f1`]; assert.ok(H.regentGrade);
  g.player.x = hoard.x; g.player.y = hoard.y; assert.ok(g.interact('open', hoard.id).ok); assert.equal(g.save.tesseracts.owned.at(-1).grade, H.regentGrade);
});

test('D6: craters of generator 2 keep the wreck on dry floor; no crater spawns a creature or its warden on lava, water or the ravine', () => {
  assert.equal(CANYON.generator, 2);
  for (const id of ['canyon:ZQ3:-5:-1', 'canyon:KX9:-26:-8']) { const seed = id.split(':')[1], v1 = generateCanyon(seed, id), m = generateCanyon(seed, id, [], [], 2), W = m.width;
    const at = (map, o) => map.tiles[o.y * W + o.x], wreck = (map) => map.objects.find((o) => o.kind === 'divineWreck');
    assert.ok(!standable(at(v1, wreck(v1))) || v1.tiles.some((t) => t.kind === 'lakeWater' && Math.hypot(t.x - wreck(v1).x, t.y - wreck(v1).y) < 2), `${id}: version 1 stays as it was`);
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) { const t = m.tiles[(wreck(m).y + dy) * W + wreck(m).x + dx]; assert.ok(!LETHAL_KINDS.has(t.kind), `${id}: dry round the wreck`); } }
  for (const seed of ['TIM1', 'A7', 'ZQ3', 'KX9']) for (let k = 0; k < 40; k++) { const id = `canyon:${seed}:${(k * 7919) % 61 - 30}:${(k * 104729) % 53 - 26}`;
    for (const V of [1, 2]) { const m = generateCanyon(seed, id, [], [], V); for (const e of m.enemySpawns) { const t = m.tiles[e.y * m.width + e.x]; assert.ok(!t.blocked && !LETHAL_KINDS.has(t.kind) && !t.chasm, `${id} v${V}: ${e.id} on ${t.kind}`); } } }
  const s = save('TIM1'); generatePinnedDungeon(s, 'canyon:TIM1:-14:-27'); assert.equal(s.consequences.dungeons['canyon:TIM1:-14:-27'].canyonGenerator, 2);
  for (const id of ['canyon:TIM1:-19:-11', 'canyon:A7:4:-18']) { const m = generatePinnedDungeon(save(id.split(':')[1]), id); // the layout variation moved these wardens into a pool
    for (const e of m.enemySpawns) { const t = m.tiles[e.y * m.width + e.x]; assert.ok(!t.blocked && !LETHAL_KINDS.has(t.kind), `${id}: ${e.id} on ${t.kind}`); } }
});

test('D8: interior v2 holes never stand over a hole below; and a fall that lands on a hole steps off it (every interior)', () => {
  for (const base of ['building:TIM1:-92:-84:keep:3', 'building:TIM1:-24:-16:hive:4r', 'building:A7:17:-40:apartment:5']) { const P = buildingPlan(base, 2);
    for (const F of P.floors) if (F.floor > 1) { const below = new Set((P.floors[F.floor - 2].holes || []).map(([x, y]) => `${x},${y}`)); for (const [x, y] of F.holes || []) assert.ok(!below.has(`${x},${y}`), `${base} f${F.floor}: ${x},${y}`); } }
  for (const base of ['castle:ZQ3:-81:-57:k:3']) { const P = castlePartPlan(base, 2); for (const F of P.floors) if (F.floor > 1) { const below = new Set((P.floors[F.floor - 2].holes || []).map(([x, y]) => `${x},${y}`)); for (const [x, y] of F.holes || []) assert.ok(!below.has(`${x},${y}`)); } }
  { const Tp = compoundTopology('TIM1', -76, -68, 'keep'); for (const p of Tp.parts) { const base = `compound:TIM1:-76:-68:keep:${p.part}:${p.floors}${p.hatch ? 'r' : ''}`, maps = Array.from({ length: p.floors }, (_, i) => generateCompoundFloor('TIM1', `${base}:f${i + 1}`, 2));
    maps.forEach((m, i) => { if (i) for (const t of m.tiles.filter((t) => t.hole)) assert.ok(!maps[i - 1].tiles[t.y * m.width + t.x].hole, `${base} f${i + 1}`); }); } }
  // runtime: a version 1 building whose hole lies over a hole (building:TIM1:-92:-84:keep:3, f3 at 2,1)
  const g = new Game(save('TIM1'), 0), id = 'building:TIM1:-92:-84:keep:3'; g.save.consequences.dungeons[`${id}:f1`] = { discovered: true, visits: 1, generatorVersion: 5 };
  const f3 = generateBuildingFloor('TIM1', `${id}:f3`), f2 = generateBuildingFloor('TIM1', `${id}:f2`), W = f3.width, h = f3.tiles.find((t) => t.hole && f2.tiles[t.y * W + t.x].hole);
  assert.ok(h, 'version 1 has a hole over a hole'); g.save.session.activeDungeonId = `${id}:f3`; g.loadArea('dungeon', false); assert.equal(g.map.building.interiorVersion, undefined);
  g.player.x = h.x; g.player.y = h.y; g.jumpUntil = 0; assert.ok(g.buildingFall()); assert.equal(g.map.building.floor, 2);
  const t = g.map.tiles[Math.round(g.player.y) * W + Math.round(g.player.x)]; assert.ok(!t.hole && !t.blocked, 'landed beside the hole, not in it'); assert.ok(Math.hypot(g.player.x - h.x, g.player.y - h.y) <= 1.5);
});

test('D9: in interior v2 a top-floor guardian always stands by its cache', () => {
  const b = generateBuildingFloor('TIM1', 'building:TIM1:-24:-16:hive:4r:f4', 2), k = generateCastleFloor('ZQ3', 'castle:ZQ3:-81:-57:k:3:f3', 2);
  assert.ok(!generateBuildingFloor('TIM1', 'building:TIM1:-24:-16:hive:4r:f4').enemySpawns.some((e) => e.buildingGuardian), 'version 1 stays as it was');
  for (const m of [b, k]) { const g = m.enemySpawns.find((e) => e.buildingGuardian), c = m.objects.find((o) => o.id === 'building-cache'); assert.ok(g && c);
    assert.ok(Math.hypot(g.x - c.x, g.y - c.y) <= BUILDINGS.interior.guardianReach); const t = m.tiles[g.y * m.width + g.x]; assert.ok(standable(t) && !t.doorway); assert.ok(!m.objects.some((o) => o.x === g.x && o.y === g.y)); }
});

test('D10/D12: haunts keep off holes, doorways and objects and clear of the way in; castle haunts stay in the courts', () => {
  let haunted = 0;
  for (const seed of ['TIM1', 'A7']) for (let k = 0; k < 30; k++) { const base = `building:${seed}:${k * 3 - 40}:${k * 5 - 60}:${['keep', 'apartment', 'hive'][k % 3]}:4`;
    for (let f = 1; f <= 4; f++) { const id = `${base}:f${f}`, plan = hauntPlan(seed, id, { interior: true }); if (!plan) continue; const m = generateBuildingFloor(seed, id, 2), sp = hauntSpawns(m, m.width, seed, id, plan); haunted++;
      assert.equal(sp.length, plan.count); for (const s of sp) { const t = m.tiles[s.y * m.width + s.x]; assert.ok(!t.hole && !t.doorway && !t.blocked, `${id}`); assert.ok(!m.objects.some((o) => o.x === s.x && o.y === s.y)); assert.ok(Math.hypot(s.x - m.entry.x, s.y - m.entry.y) >= HAUNT.clear.entry); } } }
  assert.ok(haunted > 5);
  // the overworld castle filter: courts only (the causeway outside the walls is castle ground too)
  const g = new Game(save('TIM1'), 0); g.rx = 0; g.ry = -9; g.loadArea('overworld', false);
  if (g.map.greatBuilding?.castle) for (const e of g.enemies.filter((e) => e.haunt)) { const t = g.map.tiles[Math.round(e.y) * 32 + Math.round(e.x)]; assert.ok(t.courtyard && t.greatBuilding && !t.causeway, `wisp at ${e.x},${e.y}`); }
});

test('old versions regenerate byte-identically through the pinned path', () => {
  const s = save('A7'), ids = []; for (let k = 0; k < 6; k++) { const style = ['keep', 'apartment', 'hive'][k % 3], base = `labyrinth:A7:${k * 11 - 30}:${k * 7 - 20}:${style}`, P = labyrinthPlan(base); if (P) for (const q of P.nodes.slice(0, 6)) ids.push([base, `${base}:f${q.n + 1}`]); }
  for (const [base] of ids) s.consequences.dungeons[`${base}:f1`] ||= { discovered: true, visits: 1, generatorVersion: 5 };
  for (const [, id] of ids) assert.equal(js(generatePinnedDungeon(s, id).tiles), js(generateLabyrinthChamber('A7', id).tiles), id);
  const d = save('KX9'), id = 'dungeon:KX9:g1:-17:-5:deep-v2:loop'; d.consequences.dungeons[id] = { discovered: true, visits: 1, generatorVersion: 5, layoutVersion: 1, monsterPack: 0, watcherVersion: 0 };
  const m = generatePinnedDungeon(d, id); assert.equal(d.consequences.dungeons[id].deepPlacement, undefined); assert.equal(m.deepPlacement, undefined);
  const c = save('ZQ3'); c.consequences.dungeons['canyon:ZQ3:-5:-1'] = { discovered: true, visits: 1, generatorVersion: 5 };
  assert.equal(js(generatePinnedDungeon(c, 'canyon:ZQ3:-5:-1').tiles), js(generateCanyon('ZQ3', 'canyon:ZQ3:-5:-1').tiles));
});
